window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5a0aad231485786a"]={"versions": [{"id": "FIG-5a0aad231485786a", "releases": ["R23-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Synthetisches UML-2.x-Klassendiagramm (M2-Metamodell-Referenzbeispiel).\n</li><li><strong>Architektur-Kontext:</strong> Dient in <code>AUTOSAR_FO_TPS_XMLSchemaProductionRules</code> (Foundation, Releases R23-11 / R25-11) als normatives Anschauungs- und Test-Metamodell für Kapitel 3. Es spezifiziert die formalen Ableitungsregeln, nach denen aus M2-UML-Klassen, Attributen, Assoziationen und Vererbungshierarchien W3C-XML-Schema-Definitionen (<code>.xsd</code>) für das AUTOSAR-Austauschformat (ARXML) automatisiert generiert werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Klassen / Metamodell-Elemente:</strong>\n<ul class=\"fig-list\"><li><code>A</code>: Konkrete M2-Container-Klasse (Aggregator).\n</li><li><code>B</code> (<code>{abstract}</code>): Abstrakte Basisklasse; dient als typisierter Polymorphie-Anker, besitzt selbst keine deklarierten Attribute und kann nicht direkt instanziiert werden.\n</li><li><code>B1</code>: Konkrete Subklasse von <code>B</code>; deklariert das Attribut <code>+ attB1: String</code>.\n</li><li><code>B2</code>: Konkrete Subklasse von <code>B</code>; deklariert das Attribut <code>+ attB2: String</code>.\n</li><li><code>C</code>: Konkrete M2-Klasse; deklariert das Attribut <code>+ attC: String</code>.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition <code>A</code> → <code>C</code>:</strong> Strikte kompositionelle Aggregation (gefüllte Raute bei <code>A</code>), Rollenname <code>+theC</code>, Multiplizität <code>1</code> (exakt eine Instanz von <code>C</code> obligatorisch in <code>A</code>).\n</li><li><strong>Komposition <code>A</code> → <code>B</code>:</strong> Kompositionelle Aggregation (gefüllte Raute bei <code>A</code>), Rollenname <code>+theB</code>, Multiplizität <code>*</code> (0..∞, ungebundene Liste von Instanzen abgeleiteter Klassen von <code>B</code>).\n</li><li><strong>Generalisierung / Vererbung:</strong> <code>B1</code> und <code>B2</code> spezialisieren <code>B</code> via UML-Vererbungspfeile (geschlossene hohle Pfeilspitzen).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeit-Dynamik:</strong> Nicht zutreffend (rein statisches M2-Strukturmodell; keine ECU-Laufzeit-, Task-, Det/Dem- oder OS-Interaktionen).\n</li><li><strong>Generierungs- &amp; Serialisierungssemantik (M2 → M1 ARXML):</strong>\n<ul class=\"fig-list\"><li><strong>Kardinalität <code>1</code> (<code>theC</code>):</strong> Erzeugt im <code>complexType</code> von <code>A</code> ein obligatorisches Kind-Element (bzw. Rollen-Wrapper) für <code>C</code> mit <code>minOccurs=&quot;1&quot;</code> und <code>maxOccurs=&quot;1&quot;</code>.\n</li><li><strong>Abstrakte Klasse &amp; Polymorphismus (<code>theB</code>):</strong> Da <code>B</code> abstrakt ist, generiert die XSD-Produktionsregel eine Modellgruppe (<code>xs:group</code> bzw. <code>xs:choice</code>), welche die Ersetzungen durch die konkreten Klassen <code>B1</code> und <code>B2</code> abbildet (<code>TPS_XMLSPR_00036</code>, <code>TPS_XMLSPR_00037</code>).\n</li><li><strong>Kardinalität <code>*</code> (<code>theB</code>):</strong> Gemäß den XMLSPR-Wrapping-Regeln entsteht für die Rolle <code>theB</code> entweder ein Aggregations-Wrapper-Element oder ein ungebundenes Sequenz-/Choice-Konstrukt (<code>maxOccurs=&quot;unbounded&quot;</code>), innerhalb dessen beliebige Reihenfolgen und Kombinationen von <code>B1</code>- und <code>B2</code>-Instanzen serialisiert werden dürfen (<code>TPS_XMLSPR_00038</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Schema-Validierung &amp; Tooling:</strong> \n<ul class=\"fig-list\"><li>Abstrakte M2-Klassen dürfen niemals als XML-Tag im ARXML-Dokument auftauchen (kein <code>&lt;B&gt;...&lt;/B&gt;</code>); Parser müssen an dieser Stelle ausschließlich <code>&lt;B-1&gt;</code> oder <code>&lt;B-2&gt;</code> validieren.\n</li><li>Das Fehlen des Elements <code>theC</code> führt unmittelbar zu einem Schema-Validierungsfehler (<code>cvc-complex-type.2.4</code>).\n</li></ul>\n</li><li><strong>Codegeneratoren &amp; BSW-/RTE-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>BSW-/RTE-Generatoren (z. B. DaVinci, EB tresos) mappen aggregierte Listen (<code>*</code>) in interne C-Typ-Arrays oder verkettete Zeigerstrukturen, während Kardinalität <code>1</code> als direkter Member oder nicht-optionaler Pointer typisiert wird.\n</li><li>Tool-Entwickler für AUTOSAR-Modellierungswerkzeuge müssen sicherstellen, dass Rollennamen (<code>theB</code>, <code>theC</code>) und Klassennamen (<code>B1</code>, <code>B2</code>, <code>C</code>) gemäß den Case-Convention-Regeln der XMLSPR (z. B. Upper-Camel-Case bzw. Uppercase-Hyphen-Notation) konsistent in XML-Tags transformiert werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-8e75cfc0244b6542", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Synthetisches UML-2.x-Klassendiagramm (M2-Metamodell-Referenzbeispiel).\n</li><li><strong>Architektur-Kontext:</strong> Dient in <code>AUTOSAR_FO_TPS_XMLSchemaProductionRules</code> (Foundation, Releases R23-11 / R25-11) als normatives Anschauungs- und Test-Metamodell für Kapitel 3. Es spezifiziert die formalen Ableitungsregeln, nach denen aus M2-UML-Klassen, Attributen, Assoziationen und Vererbungshierarchien W3C-XML-Schema-Definitionen (<code>.xsd</code>) für das AUTOSAR-Austauschformat (ARXML) automatisiert generiert werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Klassen / Metamodell-Elemente:</strong>\n<ul class=\"fig-list\"><li><code>A</code>: Konkrete M2-Container-Klasse (Aggregator).\n</li><li><code>B</code> (<code>{abstract}</code>): Abstrakte Basisklasse; dient als typisierter Polymorphie-Anker, besitzt selbst keine deklarierten Attribute und kann nicht direkt instanziiert werden.\n</li><li><code>B1</code>: Konkrete Subklasse von <code>B</code>; deklariert das Attribut <code>+ attB1: String</code>.\n</li><li><code>B2</code>: Konkrete Subklasse von <code>B</code>; deklariert das Attribut <code>+ attB2: String</code>.\n</li><li><code>C</code>: Konkrete M2-Klasse; deklariert das Attribut <code>+ attC: String</code>.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition <code>A</code> → <code>C</code>:</strong> Strikte kompositionelle Aggregation (gefüllte Raute bei <code>A</code>), Rollenname <code>+theC</code>, Multiplizität <code>1</code> (exakt eine Instanz von <code>C</code> obligatorisch in <code>A</code>).\n</li><li><strong>Komposition <code>A</code> → <code>B</code>:</strong> Kompositionelle Aggregation (gefüllte Raute bei <code>A</code>), Rollenname <code>+theB</code>, Multiplizität <code>*</code> (0..∞, ungebundene Liste von Instanzen abgeleiteter Klassen von <code>B</code>).\n</li><li><strong>Generalisierung / Vererbung:</strong> <code>B1</code> und <code>B2</code> spezialisieren <code>B</code> via UML-Vererbungspfeile (geschlossene hohle Pfeilspitzen).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeit-Dynamik:</strong> Nicht zutreffend (rein statisches M2-Strukturmodell; keine ECU-Laufzeit-, Task-, Det/Dem- oder OS-Interaktionen).\n</li><li><strong>Generierungs- &amp; Serialisierungssemantik (M2 → M1 ARXML):</strong>\n<ul class=\"fig-list\"><li><strong>Kardinalität <code>1</code> (<code>theC</code>):</strong> Erzeugt im <code>complexType</code> von <code>A</code> ein obligatorisches Kind-Element (bzw. Rollen-Wrapper) für <code>C</code> mit <code>minOccurs=&quot;1&quot;</code> und <code>maxOccurs=&quot;1&quot;</code>.\n</li><li><strong>Abstrakte Klasse &amp; Polymorphismus (<code>theB</code>):</strong> Da <code>B</code> abstrakt ist, generiert die XSD-Produktionsregel eine Modellgruppe (<code>xs:group</code> bzw. <code>xs:choice</code>), welche die Ersetzungen durch die konkreten Klassen <code>B1</code> und <code>B2</code> abbildet (<code>TPS_XMLSPR_00036</code>, <code>TPS_XMLSPR_00037</code>).\n</li><li><strong>Kardinalität <code>*</code> (<code>theB</code>):</strong> Gemäß den XMLSPR-Wrapping-Regeln entsteht für die Rolle <code>theB</code> entweder ein Aggregations-Wrapper-Element oder ein ungebundenes Sequenz-/Choice-Konstrukt (<code>maxOccurs=&quot;unbounded&quot;</code>), innerhalb dessen beliebige Reihenfolgen und Kombinationen von <code>B1</code>- und <code>B2</code>-Instanzen serialisiert werden dürfen (<code>TPS_XMLSPR_00038</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Schema-Validierung &amp; Tooling:</strong> \n<ul class=\"fig-list\"><li>Abstrakte M2-Klassen dürfen niemals als XML-Tag im ARXML-Dokument auftauchen (kein <code>&lt;B&gt;...&lt;/B&gt;</code>); Parser müssen an dieser Stelle ausschließlich <code>&lt;B-1&gt;</code> oder <code>&lt;B-2&gt;</code> validieren.\n</li><li>Das Fehlen des Elements <code>theC</code> führt unmittelbar zu einem Schema-Validierungsfehler (<code>cvc-complex-type.2.4</code>).\n</li></ul>\n</li><li><strong>Codegeneratoren &amp; BSW-/RTE-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>BSW-/RTE-Generatoren (z. B. DaVinci, EB tresos) mappen aggregierte Listen (<code>*</code>) in interne C-Typ-Arrays oder verkettete Zeigerstrukturen, während Kardinalität <code>1</code> als direkter Member oder nicht-optionaler Pointer typisiert wird.\n</li><li>Tool-Entwickler für AUTOSAR-Modellierungswerkzeuge müssen sicherstellen, dass Rollennamen (<code>theB</code>, <code>theC</code>) und Klassennamen (<code>B1</code>, <code>B2</code>, <code>C</code>) gemäß den Case-Convention-Regeln der XMLSPR (z. B. Upper-Camel-Case bzw. Uppercase-Hyphen-Notation) konsistent in XML-Tags transformiert werden.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-5a0aad231485786a", "to": "FIG-8e75cfc0244b6542", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8e75cfc0244b6542", "to": "FIG-5a0aad231485786a", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
